import re

def calc(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_unary()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            else:
                # truncate toward zero
                sign = -1 if (val < 0) != (rhs < 0) else 1
                val = sign * (abs(val) // abs(rhs))
        return val

    def parse_unary():
        if peek() == '-':
            advance()
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            advance()  # consume ')'
            return val
        else:
            advance()
            return int(tok)

    result = parse_expr()
    return result

